"use client";

import { CalendarDays, CheckCircle2, CircleDollarSign, Plus, RefreshCw, Settings2, Upload, UserMinus, WalletCards } from "lucide-react";
import { useCallback, useEffect, useRef, useState } from "react";
import { DataPagination, DataState, DataToolbar, InteractiveTableRow, PageHeading, Table } from "@/app/components/ui/data";
import { Badge, Button, Drawer, Field, Input, Modal, Select, Tabs, useToast } from "@/app/components/ui/primitives";
import { getSupabaseClient } from "@/app/lib/supabase";

type PaymentMethod = "unspecified"|"transfer"|"cash"|"other";
type PayablePaymentMethod = Exclude<PaymentMethod,"unspecified">;
type Collaborator = { id:string; code:string; display_name:string; job_title:string|null; employment_status:"active"|"inactive"; hired_at:string; terminated_at:string|null; payment_frequency:"weekly"|"biweekly"|"monthly"; base_pay_amount:number|null; effective_from:string|null; payment_method:PaymentMethod };
type Movement = { id:string; collaborator_id:string; movement_type:string; direction:"addition"|"reduction"|"informational"; effective_on:string; units:number|null; amount:number; description:string|null; status:"pending"|"approved"|"rejected"; calculation_metadata?:{hourly_rate?:number;daily_rate?:number;hours?:number;days?:number;multiplier?:number;paid?:boolean;formula?:string} };
type TimeOff = { id:string; kind:"vacation"|"absence"; starts_on:string; ends_on:string; days:number; status:"pending"|"approved"|"rejected"; affects_payment:boolean; notes:string|null };
type VacationBalance = { calendar_year:number; granted_days:number; adjustment_days:number; used_days:number; notes:string|null };
type Period = { id:string; payment_frequency:"weekly"|"biweekly"|"monthly"; starts_on:string; ends_on:string; payment_date:string|null; status:"draft"|"reviewing"|"approved"|"paid"; notes:string|null; total_pay:number; collaborator_count:number; payment_reference:string|null };
type PeriodConcept = { id:string; concept_code:string; label:string; direction:"addition"|"reduction"|"informational"; amount:number; units:number|null; source_date:string|null; calculation_metadata?:{hourly_rate?:number;daily_rate?:number;hours?:number;days?:number;multiplier?:number;paid?:boolean;formula?:string} };
type PeriodLine = { id:string; collaborator_id:string; collaborator_name_snapshot:string; base_pay_snapshot:number; additions_total:number; reductions_total:number; total_pay:number; payment_method:PaymentMethod; concepts:PeriodConcept[] };
type PaymentBatch = { id:string;payment_method:PayablePaymentMethod;payment_date:string;payment_reference:string;total_amount:number;recorded_at:string };
type PeriodDetail = Period & { lines:PeriodLine[]; totals:{base_pay:number;additions:number;reductions:number;total_pay:number};payment_batches:PaymentBatch[] };
type Profile = Collaborator & { compensation_history:Array<{effective_from:string;base_pay_amount:number;reason:string|null}>; vacation_balances:VacationBalance[]; time_off:TimeOff[]; movements:Movement[]; payroll_history:Array<{id:string;base_pay_snapshot:number;additions_total:number;reductions_total:number;total_pay:number;period_start:string;period_end:string;period_status:string;payment_date:string|null}> };
type CollaboratorDraft = { id?:string;code:string;displayName:string;jobTitle:string;status:"active"|"inactive";hiredAt:string;terminatedAt:string;frequency:"weekly"|"biweekly"|"monthly";basePay:string;effectiveFrom:string;reason:string };
type MovementDraft = { collaboratorId:string; movementType:string; direction:"addition"|"reduction"|"informational";effectiveOn:string;units:string;amount:string;description:string;approve:boolean };
type TimeOffDraft = { collaboratorId:string;kind:"vacation"|"absence";startsOn:string;endsOn:string;days:string;affectsPayment:boolean;notes:string;approve:boolean };
type PayrollSchedule = { payment_frequency:"weekly"|"biweekly"|"monthly" };
type OperationalSettings = { payable_days_per_period:number|null;hours_per_workday:number|null;overtime_multipliers:number[] };
type CurrentPeriod = { period:Period|null; proposed:{payment_frequency:"weekly"|"biweekly"|"monthly";starts_on:string;ends_on:string;payment_date:string|null} };
type VacationBalanceDraft = { collaboratorId:string;year:string;grantedDays:string;adjustmentDays:string;notes:string };
type TerminationDraft = { collaboratorId:string;displayName:string;hiredAt:string;terminatedAt:string;reason:string };
type MovementBatchDraft = { movementType:string;direction:"addition"|"reduction"|"informational";effectiveOn:string;approve:boolean;rows:string };
type IncidentBatchDraft = { kind:"overtime"|"absence";approve:boolean;rows:string };
type OperationalSettingsDraft = { payableDays:string;hoursPerWorkday:string;multipliers:string };
type PaymentMethodDraft = { collaboratorId:string;paymentMethod:PaymentMethod };
type PayrollLinePaymentMethodDraft = { lineId:string;collaboratorName:string;paymentMethod:PayablePaymentMethod };
type PaymentBatchDraft = { paymentMethod:PayablePaymentMethod;paymentDate:string;reference:string };
type PayrollPreflight = { included:number;missing_compensation:number;pending_movements:number;approved_movements:number;estimated_total:number };
type PendingIncident = { id:string;collaborator_id:string;collaborator_code:string;collaborator_name:string;movement_type:"overtime"|"absence";effective_on:string;amount:number;units:number|null;description:string|null;calculation_metadata:{hourly_rate?:number;daily_rate?:number;hours?:number;days?:number;multiplier?:number;paid?:boolean;formula?:string};starts_on:string|null;ends_on:string|null;days:number|null;paid:boolean|null };
type PendingIncidentsPage = { items:PendingIncident[];pagination:{page:number;page_size:number;total:number} };

const pageSize=50;
const frequencyLabel:Record<string,string>={weekly:"Semanal",biweekly:"Quincenal",monthly:"Mensual"};
const statusLabel:Record<string,string>={draft:"Preparar",reviewing:"En revisión",approved:"Aprobada",paid:"Pagada",pending:"Pendiente",active:"Activo",inactive:"Inactivo",approved_movement:"Aprobado"};
const paymentMethodLabel:Record<PaymentMethod,string>={unspecified:"Sin definir",transfer:"Transferencia",cash:"Efectivo",other:"Otro"};
const money=(value:number|null|undefined)=>new Intl.NumberFormat("es-MX",{style:"currency",currency:"MXN"}).format(Number(value??0));
const date=(value:string|null|undefined)=>value?new Intl.DateTimeFormat("es-MX",{dateStyle:"medium"}).format(new Date(`${value}T12:00:00`)):"—";
const calculationLabel=(item:Pick<PeriodConcept,"concept_code"|"calculation_metadata">)=>{const calculation=item.calculation_metadata;if(!calculation)return "";if(item.concept_code==="overtime"&&calculation.hourly_rate!==undefined)return `${money(calculation.hourly_rate)} por hora × ${calculation.hours??0} h × ${calculation.multiplier??1}`;if(item.concept_code==="absence")return calculation.paid?`Inasistencia pagada · ${calculation.days??0} días`:`${money(calculation.daily_rate)} por día × ${calculation.days??0} días`;return "";};
const tone=(status:string):"success"|"warning"|"neutral"=>status==="paid"||status==="approved"||status==="active"?"success":status==="reviewing"||status==="pending"||status==="draft"?"warning":"neutral";
const formatMoneyInput=(value:string)=>{const [whole,decimal]=value.replace(/[^\d.]/g,"").split(".",2);const formatted=(whole||"").replace(/\B(?=(\d{3})+(?!\d))/g,",");return decimal===undefined?formatted:`${formatted}.${decimal}`;};
const emptyCollaborator=():CollaboratorDraft=>({code:"",displayName:"",jobTitle:"",status:"active",hiredAt:new Date().toISOString().slice(0,10),terminatedAt:"",frequency:"weekly",basePay:"",effectiveFrom:new Date().toISOString().slice(0,10),reason:""});
const emptyMovement=(collaboratorId=""):MovementDraft=>({collaboratorId,movementType:"bonus",direction:"addition",effectiveOn:new Date().toISOString().slice(0,10),units:"",amount:"",description:"",approve:true});
const emptyTimeOff=(collaboratorId=""):TimeOffDraft=>({collaboratorId,kind:"vacation",startsOn:new Date().toISOString().slice(0,10),endsOn:new Date().toISOString().slice(0,10),days:"",affectsPayment:false,notes:"",approve:true});
const emptyVacationBalance=(collaboratorId:string,current?:VacationBalance):VacationBalanceDraft=>({collaboratorId,year:String(current?.calendar_year??new Date().getFullYear()),grantedDays:String(current?.granted_days??""),adjustmentDays:String(current?.adjustment_days??0),notes:current?.notes??""});
const emptyTermination=(profile:Profile):TerminationDraft=>({collaboratorId:profile.id,displayName:profile.display_name,hiredAt:profile.hired_at,terminatedAt:new Date().toISOString().slice(0,10),reason:""});
const emptyMovementBatch=():MovementBatchDraft=>({movementType:"bonus",direction:"addition",effectiveOn:new Date().toISOString().slice(0,10),approve:true,rows:""});
const emptyIncidentBatch=(kind:"overtime"|"absence"):IncidentBatchDraft=>({kind,approve:false,rows:""});
const operationalDraftFrom=(settings:OperationalSettings):OperationalSettingsDraft=>({payableDays:settings.payable_days_per_period===null?"":String(settings.payable_days_per_period),hoursPerWorkday:settings.hours_per_workday===null?"":String(settings.hours_per_workday),multipliers:settings.overtime_multipliers.join(", ")});
const emptyPaymentBatch=(paymentMethod:PayablePaymentMethod):PaymentBatchDraft=>({paymentMethod,paymentDate:new Date().toISOString().slice(0,10),reference:""});

export function CollaboratorsDirectoryView({companyId,permissions}:{companyId:string;permissions:string[]}) {
  const {toast}=useToast(); const [rows,setRows]=useState<Collaborator[]>([]);const [total,setTotal]=useState(0);const [page,setPage]=useState(1);const [query,setQuery]=useState("");const [debounced,setDebounced]=useState("");const [status,setStatus]=useState("active");const [loading,setLoading]=useState(true);const [error,setError]=useState<string|null>(null);const [draft,setDraft]=useState<CollaboratorDraft|null>(null);const [profile,setProfile]=useState<Profile|null>(null);const [profileTab,setProfileTab]=useState("labor");const [movement,setMovement]=useState<MovementDraft|null>(null);const [timeOff,setTimeOff]=useState<TimeOffDraft|null>(null);const [vacationBalance,setVacationBalance]=useState<VacationBalanceDraft|null>(null);const [termination,setTermination]=useState<TerminationDraft|null>(null);const [paymentMethod,setPaymentMethod]=useState<PaymentMethodDraft|null>(null);const [saving,setSaving]=useState(false);const request=useRef(0);
  const canManage=permissions.includes("manage_collaborators");const canMove=permissions.includes("manage_payroll_movements");
  useEffect(()=>{const timer=window.setTimeout(()=>{setDebounced(query.trim());setPage(1);},250);return()=>window.clearTimeout(timer);},[query]);
  const load=useCallback(async()=>{const current=++request.current;setLoading(true);setError(null);const {data,error:rpcError}=await getSupabaseClient().rpc("search_collaborators",{p_company_id:companyId,p_query:debounced||null,p_status:status||null,p_page:page,p_page_size:pageSize});if(current!==request.current)return;const result=data as {items?:Collaborator[];pagination?:{total:number}}|null;setRows(result?.items??[]);setTotal(result?.pagination?.total??0);setError(rpcError?.message??null);setLoading(false);},[companyId,debounced,page,status]);
  useEffect(()=>{void Promise.resolve().then(load);},[load]);
  const openProfile=useCallback(async(id:string)=>{setProfile(null);setProfileTab("labor");const {data,error:rpcError}=await getSupabaseClient().rpc("get_collaborator_profile",{p_company_id:companyId,p_collaborator_id:id});if(rpcError){toast({title:"No se pudo abrir el colaborador",description:rpcError.message,tone:"error"});return;}setProfile(data as Profile);},[companyId,toast]);
  async function saveCollaborator(){if(!draft)return;setSaving(true);const {data,error:rpcError}=await getSupabaseClient().rpc("save_collaborator",{p_company_id:companyId,p_collaborator_id:draft.id??null,p_code:draft.code,p_display_name:draft.displayName,p_job_title:draft.jobTitle,p_employment_status:draft.status,p_hired_at:draft.hiredAt,p_terminated_at:draft.terminatedAt||null,p_payment_frequency:draft.frequency,p_base_pay_amount:Number(draft.basePay.replace(/,/g,"")),p_effective_from:draft.effectiveFrom,p_reason:draft.reason});setSaving(false);if(rpcError){toast({title:"No se guardó el colaborador",description:rpcError.message,tone:"error"});return;}setDraft(null);setProfile(data as Profile);await load();toast({title:"Colaborador guardado",description:"El historial de sueldo conserva su vigencia.",tone:"success"});}
  async function saveMovement(){if(!movement)return;setSaving(true);const {error:rpcError}=await getSupabaseClient().rpc("save_payroll_movements_batch",{p_company_id:companyId,p_movements:[{collaborator_id:movement.collaboratorId,movement_type:movement.movementType,direction:movement.direction,effective_on:movement.effectiveOn,units:movement.units||null,amount:Number(movement.amount||0),description:movement.description}],p_approve:movement.approve});setSaving(false);if(rpcError){toast({title:"No se guardó el movimiento",description:rpcError.message,tone:"error"});return;}const collaboratorId=movement.collaboratorId;setMovement(null);await openProfile(collaboratorId);toast({title:"Movimiento registrado",description:movement.approve?"Quedó aprobado para la siguiente nómina.":"Quedó pendiente de aprobación.",tone:"success"});}
  async function saveTimeOff(){if(!timeOff)return;setSaving(true);const {error:rpcError}=await getSupabaseClient().rpc("save_collaborator_time_off",{p_company_id:companyId,p_time_off_id:null,p_collaborator_id:timeOff.collaboratorId,p_kind:timeOff.kind,p_starts_on:timeOff.startsOn,p_ends_on:timeOff.endsOn,p_days:Number(timeOff.days),p_affects_payment:timeOff.affectsPayment,p_notes:timeOff.notes,p_approve:timeOff.approve});setSaving(false);if(rpcError){toast({title:"No se guardó la ausencia",description:rpcError.message,tone:"error"});return;}const collaboratorId=timeOff.collaboratorId;setTimeOff(null);await openProfile(collaboratorId);toast({title:timeOff.kind==="vacation"?"Vacaciones registradas":"Ausencia registrada",description:timeOff.approve?"Quedó aprobada.":"Quedó pendiente de aprobación.",tone:"success"});}
  async function saveVacationBalance(){if(!vacationBalance)return;setSaving(true);const {error:rpcError}=await getSupabaseClient().rpc("save_collaborator_vacation_balance",{p_company_id:companyId,p_collaborator_id:vacationBalance.collaboratorId,p_calendar_year:Number(vacationBalance.year),p_granted_days:Number(vacationBalance.grantedDays),p_adjustment_days:Number(vacationBalance.adjustmentDays||0),p_notes:vacationBalance.notes});setSaving(false);if(rpcError){toast({title:"No se guardó el saldo",description:rpcError.message,tone:"error"});return;}const collaboratorId=vacationBalance.collaboratorId;setVacationBalance(null);await openProfile(collaboratorId);toast({title:"Saldo de vacaciones actualizado",description:"Los días usados se conservan desde las vacaciones aprobadas.",tone:"success"});}
  async function terminateCollaborator(){if(!termination)return;setSaving(true);const {data,error:rpcError}=await getSupabaseClient().rpc("terminate_collaborator",{p_company_id:companyId,p_collaborator_id:termination.collaboratorId,p_terminated_at:termination.terminatedAt,p_reason:termination.reason});setSaving(false);if(rpcError){toast({title:"No se dio de baja al colaborador",description:rpcError.message,tone:"error"});return;}setTermination(null);setProfile(data as Profile);await load();toast({title:"Colaborador dado de baja",description:"Conserva su expediente e historial; no entrará en periodos posteriores.",tone:"success"});}
  async function savePaymentMethod(){if(!paymentMethod)return;setSaving(true);const {data,error:rpcError}=await getSupabaseClient().rpc("save_collaborator_payment_method",{p_company_id:companyId,p_collaborator_id:paymentMethod.collaboratorId,p_payment_method:paymentMethod.paymentMethod});setSaving(false);if(rpcError){toast({title:"No se guardó la forma de pago",description:rpcError.message,tone:"error"});return;}setPaymentMethod(null);setProfile(data as Profile);toast({title:"Forma de pago actualizada",description:"Se usará como predeterminada en las siguientes corridas.",tone:"success"});}
  const editDraft=(value:Profile):CollaboratorDraft=>({id:value.id,code:value.code,displayName:value.display_name,jobTitle:value.job_title??"",status:value.employment_status,hiredAt:value.hired_at,terminatedAt:value.terminated_at??"",frequency:value.payment_frequency,basePay:formatMoneyInput(String(value.compensation_history[0]?.base_pay_amount??value.base_pay_amount??"")),effectiveFrom:new Date().toISOString().slice(0,10),reason:"Actualización de pago"});
  return <div className="content-frame collaborator-module">
    <PageHeading eyebrow="Colaboradores" title="Directorio" description="Expediente laboral, vacaciones y movimientos que alimentan la nómina." action={canManage?<Button variant="primary" onClick={()=>setDraft(emptyCollaborator())}><Plus size={16}/>Nuevo colaborador</Button>:undefined}/>
    <DataToolbar search={query} onSearchChange={setQuery} placeholder="Buscar por nombre, código o puesto" results={total} filters={<Select ariaLabel="Estado de colaborador" value={status||"all"} onValueChange={value=>{setStatus(value==="all"?"":value);setPage(1);}} options={[{value:"all",label:"Todos"},{value:"active",label:"Activos"},{value:"inactive",label:"Inactivos"}]}/>}/>
    <DataState loading={loading} error={error} hasData={rows.length} empty="Crea colaboradores o impórtalos desde el Centro de migraciones." emptyAction={canManage?<Button size="sm" onClick={()=>setDraft(emptyCollaborator())}>Crear colaborador</Button>:undefined}>
      <Table><thead><tr><th>Colaborador</th><th>Puesto</th><th>Pago base</th><th>Periodicidad</th><th>Ingreso</th><th>Estado</th></tr></thead><tbody>{rows.map(row=><InteractiveTableRow key={row.id} label={`Abrir ${row.display_name}`} onActivate={()=>void openProfile(row.id)}><td><strong>{row.display_name}</strong><small>{row.code}</small></td><td>{row.job_title??"—"}</td><td>{row.base_pay_amount===null?"Sin sueldo vigente":money(row.base_pay_amount)}</td><td>{frequencyLabel[row.payment_frequency]}</td><td>{date(row.hired_at)}</td><td><Badge tone={row.employment_status==="active"?"success":"neutral"}>{statusLabel[row.employment_status]}</Badge></td></InteractiveTableRow>)}</tbody></Table>
      <DataPagination page={page} onChange={setPage} total={total} pageSize={pageSize} label="colaboradores"/>
    </DataState>
    <Drawer open={Boolean(draft)} onOpenChange={open=>!open&&!saving&&setDraft(null)} title={draft?.id?"Editar colaborador":"Nuevo colaborador"} className="collaborator-drawer">{draft&&<form className="drawer-form" onSubmit={event=>{event.preventDefault();void saveCollaborator();}}>
      <section>
        <h3>Datos laborales</h3>
        {!draft.id&&<p>Satrapy asignará el código automáticamente al guardar.</p>}
        <div className="form-grid">
          <Field label="Nombre completo"><Input required value={draft.displayName} onChange={event=>setDraft({...draft,displayName:event.target.value})}/></Field>
          <Field label="Puesto"><Input value={draft.jobTitle} onChange={event=>setDraft({...draft,jobTitle:event.target.value})}/></Field>
          <Field label="Fecha de ingreso"><Input required type="date" value={draft.hiredAt} onChange={event=>setDraft({...draft,hiredAt:event.target.value,...(!draft.id?{effectiveFrom:event.target.value}: {})})}/></Field>
        </div>
      </section>
      <section>
        <h3>Pago</h3>
        <p>Define el importe y la periodicidad del colaborador.</p>
        <div className="form-grid">
          <Field label="Periodicidad"><Select ariaLabel="Periodicidad" value={draft.frequency} onValueChange={value=>setDraft({...draft,frequency:value as CollaboratorDraft["frequency"]})} options={[{value:"weekly",label:"Semanal"},{value:"biweekly",label:"Quincenal"},{value:"monthly",label:"Mensual"}]}/></Field>
          <Field label="Pago base"><Input required inputMode="decimal" value={draft.basePay} onChange={event=>setDraft({...draft,basePay:formatMoneyInput(event.target.value)})}/></Field>
          {draft.id&&<Field label="Vigente desde"><Input required type="date" value={draft.effectiveFrom} onChange={event=>setDraft({...draft,effectiveFrom:event.target.value})}/></Field>}
          {draft.id&&<Field label="Motivo del cambio"><Input required value={draft.reason} onChange={event=>setDraft({...draft,reason:event.target.value})} placeholder="Describe la actualización"/></Field>}
        </div>
      </section>
      <div className="drawer-actions"><Button onClick={()=>setDraft(null)} disabled={saving}>Cancelar</Button><Button type="submit" variant="primary" loading={saving}>Guardar colaborador</Button></div>
    </form>}</Drawer>
    <Drawer open={Boolean(profile)} onOpenChange={open=>!open&&setProfile(null)} title={profile?.display_name??"Colaborador"} className="collaborator-profile">{profile&&<><div className="collaborator-profile__summary"><span>{profile.code}</span><strong>{profile.job_title??"Sin puesto"}</strong><Badge tone={profile.employment_status==="active"?"success":"neutral"}>{statusLabel[profile.employment_status]}</Badge></div><Tabs value={profileTab} onValueChange={setProfileTab} items={[{value:"labor",label:"Laboral"},{value:"time",label:"Vacaciones"},{value:"movements",label:"Movimientos"},{value:"history",label:"Pagos"}]}/>{profileTab==="labor"&&<div className="profile-section"><div className="profile-metric"><span>Pago vigente</span><strong>{money(profile.compensation_history[0]?.base_pay_amount??profile.base_pay_amount)}</strong><small>{frequencyLabel[profile.payment_frequency]} · vigente desde {date(profile.compensation_history[0]?.effective_from)}</small></div><div className="profile-grid"><div><span>Ingreso</span><strong>{date(profile.hired_at)}</strong></div><div><span>Forma de pago</span><strong>{paymentMethodLabel[profile.payment_method??"unspecified"]}</strong></div><div><span>Baja</span><strong>{date(profile.terminated_at)}</strong></div></div><h3>Historial salarial</h3><ul className="history-list">{profile.compensation_history.map(entry=><li key={entry.effective_from}><span>{date(entry.effective_from)}</span><strong>{money(entry.base_pay_amount)}</strong><small>{entry.reason??"Sin observación"}</small></li>)}</ul>{canManage&&<div className="profile-section__actions"><Button variant="secondary" onClick={()=>setDraft(editDraft(profile))}>Editar datos laborales</Button><Button variant="secondary" onClick={()=>setPaymentMethod({collaboratorId:profile.id,paymentMethod:profile.payment_method??"unspecified"})}>Forma de pago</Button>{profile.employment_status==="active"&&<Button variant="danger" onClick={()=>setTermination(emptyTermination(profile))}><UserMinus size={15}/>Dar de baja</Button>}</div>}</div>}{profileTab==="time"&&<div className="profile-section"><div className="profile-section__header"><div><h3>Vacaciones y ausencias</h3><p>Registra vacaciones aquí. Las inasistencias que afectan la nómina se capturan desde Nómina → Inasistencias.</p></div>{canMove&&<div className="profile-section__actions"><Button size="sm" variant="secondary" onClick={()=>setVacationBalance(emptyVacationBalance(profile.id,profile.vacation_balances.find(item=>item.calendar_year===new Date().getFullYear())))}>Ajustar saldo</Button><Button size="sm" variant="primary" onClick={()=>setTimeOff(emptyTimeOff(profile.id))}><CalendarDays size={15}/>Registrar vacaciones</Button></div>}</div><div className="vacation-balances">{profile.vacation_balances.length?profile.vacation_balances.map(balance=><article key={balance.calendar_year}><span>{balance.calendar_year}</span><strong>{Number(balance.granted_days)+Number(balance.adjustment_days)-Number(balance.used_days)} días</strong><small>{balance.used_days} usados</small></article>):<p>Aún no hay saldo de vacaciones registrado.</p>}</div><ul className="history-list">{profile.time_off.map(item=><li key={item.id}><span>{item.kind==="vacation"?"Vacaciones":"Ausencia"}</span><strong>{date(item.starts_on)} – {date(item.ends_on)} · {item.days} días</strong><Badge tone={item.status==="approved"?"success":"warning"}>{item.status==="approved"?"Aprobado":"Pendiente"}</Badge></li>)}</ul></div>}{profileTab==="movements"&&<div className="profile-section"><div className="profile-section__header"><div><h3>Movimientos de nómina</h3><p>Bonos, aguinaldo, prima vacacional y ajustes aprobados se incorporan a la siguiente corrida aplicable.</p></div>{canMove&&<Button size="sm" variant="primary" onClick={()=>setMovement(emptyMovement(profile.id))}><Plus size={15}/>Registrar otro concepto</Button>}</div><ul className="history-list">{profile.movements.map(item=><li key={item.id}><span>{movementLabel(item.movement_type)}</span><strong className={item.direction==="reduction"?"is-reduction":""}>{item.direction==="reduction"?"−":item.direction==="addition"?"+":""}{money(item.amount)}</strong><small>{date(item.effective_on)}{item.units?` · ${item.units} unidades`:""}{item.description?` · ${item.description}`:""}</small><Badge tone={item.status==="approved"?"success":"warning"}>{item.status==="approved"?"Aprobado":"Pendiente"}</Badge></li>)}</ul></div>}{profileTab==="history"&&<div className="profile-section"><h3>Historial de pagos</h3><ul className="history-list">{profile.payroll_history.map(item=><li key={item.id}><span>{date(item.period_start)} – {date(item.period_end)}</span><strong>{money(item.total_pay)}</strong><small>Base {money(item.base_pay_snapshot)} · Extras {money(item.additions_total)} · Ajustes {money(item.reductions_total)}</small><Badge tone={tone(item.period_status)}>{statusLabel[item.period_status]}</Badge></li>)}</ul></div>}</>}</Drawer>
    <PaymentMethodModal draft={paymentMethod} saving={saving} onChange={setPaymentMethod} onClose={()=>setPaymentMethod(null)} onSave={()=>void savePaymentMethod()}/>
    <MovementModal draft={movement} saving={saving} onChange={setMovement} onClose={()=>setMovement(null)} onSave={()=>void saveMovement()}/><TimeOffModal draft={timeOff} saving={saving} onChange={setTimeOff} onClose={()=>setTimeOff(null)} onSave={()=>void saveTimeOff()}/><VacationBalanceModal draft={vacationBalance} saving={saving} onChange={setVacationBalance} onClose={()=>setVacationBalance(null)} onSave={()=>void saveVacationBalance()}/><TerminationModal draft={termination} saving={saving} onChange={setTermination} onClose={()=>setTermination(null)} onSave={()=>void terminateCollaborator()}/>
  </div>;
}

export function PayrollView({companyId,permissions}:{companyId:string;permissions:string[]}) {
  const {toast}=useToast();
  const [rows,setRows]=useState<Period[]>([]);const [total,setTotal]=useState(0);const [page,setPage]=useState(1);const [loading,setLoading]=useState(true);const [error,setError]=useState<string|null>(null);
  const [schedule,setSchedule]=useState<PayrollSchedule>({payment_frequency:"weekly"});const [settings,setSettings]=useState<OperationalSettings>({payable_days_per_period:null,hours_per_workday:null,overtime_multipliers:[]});const [settingsDraft,setSettingsDraft]=useState<OperationalSettingsDraft>({payableDays:"",hoursPerWorkday:"",multipliers:""});const [scheduleOpen,setScheduleOpen]=useState(false);
  const [current,setCurrent]=useState<CurrentPeriod|null>(null);const [preflight,setPreflight]=useState<PayrollPreflight|null>(null);const [detail,setDetail]=useState<PeriodDetail|null>(null);const [movementBatch,setMovementBatch]=useState<MovementBatchDraft|null>(null);const [incidentBatch,setIncidentBatch]=useState<IncidentBatchDraft|null>(null);const [pendingIncidents,setPendingIncidents]=useState<PendingIncident[]>([]);const [pendingIncidentsTotal,setPendingIncidentsTotal]=useState(0);const [pendingIncidentsPage,setPendingIncidentsPage]=useState(1);const [pendingOpen,setPendingOpen]=useState(false);const [selectedIncidents,setSelectedIncidents]=useState<string[]>([]);const [linePaymentMethod,setLinePaymentMethod]=useState<PayrollLinePaymentMethodDraft|null>(null);const [paymentBatch,setPaymentBatch]=useState<PaymentBatchDraft|null>(null);const [saving,setSaving]=useState(false);
  const canManage=permissions.includes("manage_payroll_runs");const canMove=permissions.includes("manage_payroll_movements");const canApprove=permissions.includes("approve_payroll_runs");const canPay=permissions.includes("mark_payroll_paid");
  const incidentsReady=Boolean(settings.payable_days_per_period&&settings.hours_per_workday&&settings.overtime_multipliers.length);
  const load=useCallback(async()=>{setLoading(true);setError(null);const client=getSupabaseClient();const [periods,scheduleResult,currentResult,preflightResult,settingsResult,pendingResult]=await Promise.all([client.rpc("search_payroll_periods",{p_company_id:companyId,p_page:page,p_page_size:pageSize}),client.rpc("get_payroll_schedule",{p_company_id:companyId}),client.rpc("get_current_payroll_period",{p_company_id:companyId}),client.rpc("get_payroll_preflight",{p_company_id:companyId}),client.rpc("get_payroll_operational_settings",{p_company_id:companyId}),client.rpc("get_pending_payroll_incidents",{p_company_id:companyId,p_page:pendingIncidentsPage,p_page_size:100})]);const result=periods.data as {items?:Period[];pagination?:{total:number}}|null;const pending=pendingResult.data as PendingIncidentsPage|null;setRows(result?.items??[]);setTotal(result?.pagination?.total??0);setSchedule((scheduleResult.data as PayrollSchedule|null)??{payment_frequency:"weekly"});setCurrent(currentResult.data as CurrentPeriod|null);setPreflight(preflightResult.data as PayrollPreflight|null);setSettings((settingsResult.data as OperationalSettings|null)??{payable_days_per_period:null,hours_per_workday:null,overtime_multipliers:[]});setPendingIncidents(pending?.items??[]);setPendingIncidentsTotal(pending?.pagination?.total??0);setError(periods.error?.message??scheduleResult.error?.message??currentResult.error?.message??preflightResult.error?.message??null);setLoading(false);},[companyId,page,pendingIncidentsPage]);useEffect(()=>{void Promise.resolve().then(load);},[load]);
  const openDetail=useCallback(async(id:string)=>{const {data,error:rpcError}=await getSupabaseClient().rpc("get_payroll_period",{p_company_id:companyId,p_period_id:id});if(rpcError){toast({title:"No se pudo abrir la nómina",description:rpcError.message,tone:"error"});return;}setDetail(data as PeriodDetail);},[companyId,toast]);
  function openSettings(){setSettingsDraft(operationalDraftFrom(settings));setScheduleOpen(true);}
  function openIncidentCapture(kind:"overtime"|"absence"){if(!incidentsReady){toast({title:"Falta configurar la nómina",description:"Define días pagables, horas por jornada y multiplicadores antes de registrar incidencias.",tone:"info"});openSettings();return;}setIncidentBatch(emptyIncidentBatch(kind));}
  async function saveOperationalSettings(){const multipliers=settingsDraft.multipliers.split(",").map(item=>Number(item.trim())).filter(Number.isFinite);const payableDays=Number(settingsDraft.payableDays);const hoursPerWorkday=Number(settingsDraft.hoursPerWorkday);if(!Number.isFinite(payableDays)||payableDays<=0||!Number.isFinite(hoursPerWorkday)||hoursPerWorkday<=0||!multipliers.length||multipliers.some(value=>value<=0)){toast({title:"Revisa la configuración",description:"Define días pagables, horas por jornada y al menos un multiplicador positivo.",tone:"error"});return;}setSaving(true);const {error:rpcError}=await getSupabaseClient().rpc("save_payroll_operational_configuration",{p_company_id:companyId,p_payment_frequency:schedule.payment_frequency,p_payable_days_per_period:payableDays,p_hours_per_workday:hoursPerWorkday,p_overtime_multipliers:multipliers});setSaving(false);if(rpcError){toast({title:"No se guardó la configuración",description:rpcError.message,tone:"error"});return;}setScheduleOpen(false);await load();toast({title:"Configuración actualizada",description:"Las nuevas incidencias usarán estas reglas de cálculo.",tone:"success"});}
  async function startCurrent(){setSaving(true);const {data,error:rpcError}=await getSupabaseClient().rpc("start_current_payroll",{p_company_id:companyId});setSaving(false);if(rpcError){toast({title:"No se pudo preparar la nómina",description:rpcError.message,tone:"error"});return;}setDetail(data as PeriodDetail);await load();toast({title:"Nómina preparada",description:"Revisa los importes antes de aprobar.",tone:"success"});}
  async function collaboratorsByCode(){const {data,error:rpcError}=await getSupabaseClient().rpc("search_collaborators",{p_company_id:companyId,p_query:null,p_status:"active",p_page:1,p_page_size:100});return {collaborators:(data as {items?:Collaborator[]}|null)?.items??[],error:rpcError};}
  async function saveMovementBatch(){if(!movementBatch)return;const parsed=movementBatch.rows.trim().split(/\r?\n/).filter(Boolean).map((line,index)=>{const [code,amount,units="",...description]=line.split("\t");return {line:index+1,code:code?.trim().toUpperCase(),amount:Number(amount?.replace(/,/g,"")),units:units.trim(),description:description.join("\t").trim()};});if(!parsed.length||parsed.length>100||parsed.some(row=>!row.code||!Number.isFinite(row.amount)||row.amount<0)){toast({title:"Revisa el lote",description:"Pega entre 1 y 100 renglones válidos: código, importe, unidades y descripción.",tone:"error"});return;}setSaving(true);const {collaborators,error:collaboratorError}=await collaboratorsByCode();const byCode=new Map(collaborators.map(item=>[item.code.toUpperCase(),item.id]));const missing=parsed.find(row=>!byCode.has(row.code));if(collaboratorError||missing){setSaving(false);toast({title:"No se guardó el lote",description:collaboratorError?.message??`No se encontró el código ${missing?.code}.`,tone:"error"});return;}const {error:rpcError}=await getSupabaseClient().rpc("save_payroll_movements_batch",{p_company_id:companyId,p_movements:parsed.map(row=>({collaborator_id:byCode.get(row.code),movement_type:movementBatch.movementType,direction:movementBatch.direction,effective_on:movementBatch.effectiveOn,units:row.units||null,amount:row.amount,description:row.description||null})),p_approve:movementBatch.approve});setSaving(false);if(rpcError){toast({title:"No se guardó el lote",description:rpcError.message,tone:"error"});return;}const saved=parsed.length;setMovementBatch(null);await load();toast({title:"Movimientos registrados",description:`Se guardaron ${saved} movimientos en una sola operación.`,tone:"success"});}
  async function saveIncidentBatch(){if(!incidentBatch)return;const parsed=incidentBatch.rows.trim().split(/\r?\n/).filter(Boolean).map((line,index)=>{const cells=line.split("\t");if(incidentBatch.kind==="overtime"){const [code,effectiveOn,hours,multiplier,...description]=cells;return {line:index+1,code:code?.trim().toUpperCase(),effectiveOn:effectiveOn?.trim(),hours:Number(hours),multiplier:Number(multiplier),description:description.join("\t").trim()};}const [code,startsOn,endsOn,days,paid,...description]=cells;return {line:index+1,code:code?.trim().toUpperCase(),startsOn:startsOn?.trim(),endsOn:endsOn?.trim(),days:Number(days),paid:paid?.trim().toLowerCase(),description:description.join("\t").trim()};});const invalid=incidentBatch.kind==="overtime"?parsed.some(row=>!row.code||!row.effectiveOn||!Number.isFinite(row.hours)||row.hours<=0||!Number.isFinite(row.multiplier)||row.multiplier<=0):parsed.some(row=>!row.code||!row.startsOn||!row.endsOn||!Number.isFinite(row.days)||row.days<=0||!(row.paid==="pagada"||row.paid==="no_pagada"));if(!parsed.length||parsed.length>100||invalid){toast({title:"Revisa el lote",description:incidentBatch.kind==="overtime"?"Usa entre 1 y 100 renglones: código, fecha, horas, multiplicador y descripción.":"Usa entre 1 y 100 renglones: código, inicio, fin, días, pagada o no_pagada y descripción.",tone:"error"});return;}setSaving(true);const {collaborators,error:collaboratorError}=await collaboratorsByCode();const byCode=new Map(collaborators.map(item=>[item.code.toUpperCase(),item.id]));const missing=parsed.find(row=>!byCode.has(row.code));if(collaboratorError||missing){setSaving(false);toast({title:"No se guardó el lote",description:collaboratorError?.message??`No se encontró el código ${missing?.code}.`,tone:"error"});return;}const incidents=incidentBatch.kind==="overtime"?parsed.map(row=>({kind:"overtime",collaborator_id:byCode.get(row.code),effective_on:row.effectiveOn,hours:row.hours,multiplier:row.multiplier,description:row.description||null})):parsed.map(row=>({kind:"absence",collaborator_id:byCode.get(row.code),starts_on:row.startsOn,ends_on:row.endsOn,days:row.days,paid:row.paid==="pagada",description:row.description||null}));const {error:rpcError}=await getSupabaseClient().rpc("save_payroll_incidents_batch",{p_company_id:companyId,p_incidents:incidents,p_approve:incidentBatch.approve});setSaving(false);if(rpcError){toast({title:"No se guardaron las incidencias",description:rpcError.message,tone:"error"});return;}const saved=parsed.length;setIncidentBatch(null);await load();toast({title:incidentBatch.kind==="overtime"?"Horas extra capturadas":"Inasistencias capturadas",description:`Se guardaron ${saved} incidencias en una sola operación${incidentBatch.approve?" y quedaron aprobadas.":"."}`,tone:"success"});}
  async function resolvePendingIncidents(action:"approve"|"reject"){if(!selectedIncidents.length)return;setSaving(true);const {error:rpcError}=await getSupabaseClient().rpc("resolve_payroll_incidents_batch",{p_company_id:companyId,p_movement_ids:selectedIncidents,p_action:action});setSaving(false);if(rpcError){toast({title:"No se actualizaron las incidencias",description:rpcError.message,tone:"error"});return;}const count=selectedIncidents.length;setSelectedIncidents([]);await load();toast({title:action==="approve"?"Incidencias aprobadas":"Incidencias rechazadas",description:`Se actualizaron ${count} incidencias.`,tone:"success"});}
  async function savePayrollLinePaymentMethod(){if(!linePaymentMethod||!detail)return;setSaving(true);const {data,error:rpcError}=await getSupabaseClient().rpc("set_payroll_line_payment_method",{p_company_id:companyId,p_period_line_id:linePaymentMethod.lineId,p_payment_method:linePaymentMethod.paymentMethod});setSaving(false);if(rpcError){toast({title:"No se actualizó la forma de pago",description:rpcError.message,tone:"error"});return;}setLinePaymentMethod(null);setDetail(data as PeriodDetail);toast({title:"Forma de pago ajustada",description:"El cambio sólo aplica a esta corrida.",tone:"success"});}
  async function recordPaymentBatch(){if(!paymentBatch||!detail)return;setSaving(true);const {data,error:rpcError}=await getSupabaseClient().rpc("record_payroll_payment_batch",{p_company_id:companyId,p_period_id:detail.id,p_payment_method:paymentBatch.paymentMethod,p_payment_date:paymentBatch.paymentDate,p_payment_reference:paymentBatch.reference});setSaving(false);if(rpcError){toast({title:"No se registró el pago",description:rpcError.message,tone:"error"});return;}const method=paymentMethodLabel[paymentBatch.paymentMethod];setPaymentBatch(null);setDetail(data as PeriodDetail);await load();toast({title:"Pago registrado",description:`El grupo de ${method.toLowerCase()} quedó registrado.`,tone:"success"});}
  async function advance(action:"prepare"|"approve"){if(!detail)return;setSaving(true);const rpc=action==="prepare"?"prepare_payroll_period":"advance_payroll_period";const params=action==="prepare"?{p_company_id:companyId,p_period_id:detail.id}:{p_company_id:companyId,p_period_id:detail.id,p_action:action,p_payment_reference:null};const {data,error:rpcError}=await getSupabaseClient().rpc(rpc,params);setSaving(false);if(rpcError){toast({title:"No se actualizó la nómina",description:rpcError.message,tone:"error"});return;}setDetail(data as PeriodDetail);await load();toast({title:action==="prepare"?"Nómina preparada":"Nómina aprobada",description:action==="prepare"?"Revisa los importes antes de aprobar.":"Ahora registra los pagos agrupados por forma de pago.",tone:"success"});}
  const activePeriod=current?.period??current?.proposed;
  const activePeriodAction=current?.period?()=>void openDetail(current.period!.id):()=>void startCurrent();
  return <div className="content-frame collaborator-module payroll-module">
    <PageHeading eyebrow="Colaboradores · Nómina" title="Nómina" description="Preparación, revisión y seguimiento de pagos." action={<div className="payroll-heading-actions">{canMove&&<><Button variant="secondary" onClick={()=>openIncidentCapture("overtime")}>Horas extra</Button><Button variant="secondary" onClick={()=>openIncidentCapture("absence")}>Inasistencias</Button><Button variant="secondary" onClick={()=>{setSelectedIncidents([]);setPendingIncidentsPage(1);setPendingOpen(true);}}>Pendientes{pendingIncidentsTotal?` (${pendingIncidentsTotal})`:""}</Button><Button variant="secondary" onClick={()=>setMovementBatch(emptyMovementBatch())}><Upload size={16}/>Otros conceptos</Button></>}{canManage&&<Button variant="secondary" onClick={openSettings}><Settings2 size={16}/>Configuración</Button>}</div>}/>
    <section className="payroll-current"><div><span className="eyebrow">Periodo vigente</span><strong>{activePeriod?`${date(activePeriod.starts_on)} – ${date(activePeriod.ends_on)}`:"Cargando periodo"}</strong><small>{activePeriod?frequencyLabel[activePeriod.payment_frequency]:""}</small></div>{canManage&&<Button variant="primary" loading={saving} onClick={activePeriodAction}><RefreshCw size={16}/>{current?.period?"Abrir nómina vigente":"Preparar nómina vigente"}</Button>}</section>
    {!incidentsReady&&<section className="payroll-guide"><Settings2 size={20}/><span>Configura días pagables, jornada y multiplicadores antes de capturar incidencias.</span></section>}
    {preflight&&<section className="payroll-preflight" style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:16,border:"1px solid var(--line)",borderRadius:"var(--radius-md)",background:"var(--surface)",padding:"11px 13px"}}><div style={{display:"grid",gap:3}}><span style={{color:"var(--muted)",fontSize:10}}>Antes de preparar</span><strong style={{color:"var(--ink)",fontSize:13}}>{preflight.included} colaboradores · {money(preflight.estimated_total)} estimado</strong></div><div style={{display:"flex",flexWrap:"wrap",justifyContent:"flex-end",gap:10,color:"var(--muted)",fontSize:10}}><span style={{color:"#a3483d"}}>{preflight.missing_compensation} sin pago vigente</span><span>{preflight.pending_movements} movimientos pendientes</span><span>{preflight.approved_movements} movimientos aprobados</span></div></section>}
    <section className="payroll-guide"><CircleDollarSign size={20}/><span>Flujo: <strong>Incidencias</strong> calcula y registra; <strong>Preparar</strong> toma sólo las aprobadas para la corrida.</span></section>
    <DataState loading={loading} error={error} hasData={rows.length} empty="Aún no hay nóminas registradas."><Table><thead><tr><th>Periodo</th><th>Pago</th><th>Colaboradores</th><th>Total estimado</th><th>Estado</th></tr></thead><tbody>{rows.map(row=><InteractiveTableRow key={row.id} label={`Abrir nómina ${date(row.starts_on)}`} onActivate={()=>void openDetail(row.id)}><td><strong>{date(row.starts_on)} – {date(row.ends_on)}</strong><small>{frequencyLabel[row.payment_frequency]} · Pago {date(row.payment_date)}</small></td><td>{row.payment_reference??"—"}</td><td>{row.collaborator_count}</td><td>{money(row.total_pay)}</td><td><Badge tone={tone(row.status)}>{statusLabel[row.status]}</Badge></td></InteractiveTableRow>)}</tbody></Table><DataPagination page={page} onChange={setPage} total={total} pageSize={pageSize} label="periodos"/></DataState>
    <Modal open={scheduleOpen} onOpenChange={open=>!open&&!saving&&setScheduleOpen(false)} eyebrow="Nómina" title="Configuración de nómina" description="Estas reglas se guardan por empresa y se aplican al calcular nuevas incidencias." footer={<><Button disabled={saving} onClick={()=>setScheduleOpen(false)}>Cancelar</Button><Button variant="primary" loading={saving} onClick={()=>void saveOperationalSettings()}>Guardar configuración</Button></>}><div className="form-grid"><Field label="Periodicidad"><Select ariaLabel="Periodicidad" value={schedule.payment_frequency} onValueChange={value=>setSchedule({payment_frequency:value as PayrollSchedule["payment_frequency"]})} options={[{value:"weekly",label:"Semanal"},{value:"biweekly",label:"Quincenal"},{value:"monthly",label:"Mensual"}]}/></Field><Field label="Días pagables por periodo"><Input required inputMode="decimal" value={settingsDraft.payableDays} onChange={event=>setSettingsDraft({...settingsDraft,payableDays:event.target.value})} placeholder="Ej. 7"/></Field><Field label="Horas por jornada"><Input required inputMode="decimal" value={settingsDraft.hoursPerWorkday} onChange={event=>setSettingsDraft({...settingsDraft,hoursPerWorkday:event.target.value})} placeholder="Ej. 8"/></Field><Field label="Multiplicadores autorizados"><Input required value={settingsDraft.multipliers} onChange={event=>setSettingsDraft({...settingsDraft,multipliers:event.target.value})} placeholder="Ej. 1.5, 2"/></Field></div></Modal>
    <IncidentBatchModal draft={incidentBatch} saving={saving} multipliers={settings.overtime_multipliers} onChange={setIncidentBatch} onClose={()=>setIncidentBatch(null)} onSave={()=>void saveIncidentBatch()}/>
    <PendingIncidentsModal open={pendingOpen} items={pendingIncidents} total={pendingIncidentsTotal} page={pendingIncidentsPage} selected={selectedIncidents} saving={saving} onClose={()=>setPendingOpen(false)} onToggle={id=>setSelectedIncidents(current=>current.includes(id)?current.filter(item=>item!==id):[...current,id])} onToggleAll={()=>setSelectedIncidents(current=>current.length===pendingIncidents.length?[]:pendingIncidents.map(item=>item.id))} onPageChange={next=>{setSelectedIncidents([]);setPendingIncidentsPage(next);}} onResolve={action=>void resolvePendingIncidents(action)}/>
    <MovementBatchModal draft={movementBatch} saving={saving} onChange={setMovementBatch} onClose={()=>setMovementBatch(null)} onSave={()=>void saveMovementBatch()}/>
    <Drawer open={Boolean(detail)} onOpenChange={open=>!open&&!saving&&setDetail(null)} title={detail?`Nómina · ${date(detail.starts_on)} – ${date(detail.ends_on)}`:"Nómina"} className="payroll-detail">{detail&&<><div className="payroll-detail__summary"><article><span>Total estimado</span><strong>{money(detail.totals.total_pay)}</strong></article><article><span>Colaboradores</span><strong>{detail.lines.length}</strong></article><Badge tone={tone(detail.status)}>{statusLabel[detail.status]}</Badge></div>{detail.status==="draft"&&canManage&&<section className="payroll-action-card"><div><strong>Lista para preparar</strong><span>Calcula el pago base proporcional y toma las incidencias y movimientos aprobados del corte.</span></div><Button variant="primary" loading={saving} onClick={()=>void advance("prepare")}><RefreshCw size={16}/>Preparar nómina</Button></section>}{detail.status==="reviewing"&&canApprove&&<section className="payroll-action-card"><div><strong>Revisión final</strong><span>Al aprobar, los movimientos utilizados no podrán modificarse; un ajuste irá al siguiente periodo.</span></div><Button variant="primary" loading={saving} onClick={()=>void advance("approve")}><CheckCircle2 size={16}/>Aprobar nómina</Button></section>}{detail.status==="approved"&&canPay&&<PayrollPaymentGroups detail={detail} saving={saving} onLineMethod={line=>setLinePaymentMethod({lineId:line.id,collaboratorName:line.collaborator_name_snapshot,paymentMethod:line.payment_method==="cash"||line.payment_method==="other"?line.payment_method:"transfer"})} onRecord={method=>setPaymentBatch(emptyPaymentBatch(method))}/>} {detail.status!=="draft"&&<Table className="payroll-detail__table"><thead><tr><th>Colaborador</th><th>Base</th><th>Extras</th><th>Ajustes</th><th>Total</th></tr></thead><tbody>{detail.lines.map(line=><tr key={line.id}><td><strong>{line.collaborator_name_snapshot}</strong><small>{line.concepts.filter(item=>item.concept_code!=="base_pay").map(item=>{const calculation=calculationLabel(item);return `${item.label}: ${item.direction==="reduction"?"−":"+"}${money(item.amount)}${calculation?` (${calculation})`:""}`;}).join(" · ")||"Sin movimientos"}</small></td><td>{money(line.base_pay_snapshot)}</td><td>{money(line.additions_total)}</td><td>{line.reductions_total?`−${money(line.reductions_total)}`:"—"}</td><td><strong>{money(line.total_pay)}</strong></td></tr>)}</tbody></Table>}</>}</Drawer>
    <PayrollLinePaymentMethodModal draft={linePaymentMethod} saving={saving} onChange={setLinePaymentMethod} onClose={()=>setLinePaymentMethod(null)} onSave={()=>void savePayrollLinePaymentMethod()}/>
    <PayrollPaymentBatchModal draft={paymentBatch} saving={saving} onChange={setPaymentBatch} onClose={()=>setPaymentBatch(null)} onSave={()=>void recordPaymentBatch()}/>
  </div>;
}

function PaymentMethodModal({draft,saving,onChange,onClose,onSave}:{draft:PaymentMethodDraft|null;saving:boolean;onChange:(draft:PaymentMethodDraft|null)=>void;onClose:()=>void;onSave:()=>void}){return <Modal open={Boolean(draft)} onOpenChange={open=>!open&&!saving&&onClose()} eyebrow="Colaborador" title="Forma de pago predeterminada" description="Se conservará en el expediente y se propondrá al registrar el pago de una corrida." footer={<><Button disabled={saving} onClick={onClose}>Cancelar</Button><Button variant="primary" loading={saving} onClick={onSave}>Guardar</Button></>}>{draft&&<Field label="Forma de pago"><Select ariaLabel="Forma de pago" value={draft.paymentMethod} onValueChange={value=>onChange({...draft,paymentMethod:value as PaymentMethod})} options={[{value:"unspecified",label:"Sin definir"},{value:"transfer",label:"Transferencia"},{value:"cash",label:"Efectivo"},{value:"other",label:"Otro"}]}/></Field>}</Modal>}
function IncidentBatchModal({draft,saving,multipliers,onChange,onClose,onSave}:{draft:IncidentBatchDraft|null;saving:boolean;multipliers:number[];onChange:(draft:IncidentBatchDraft|null)=>void;onClose:()=>void;onSave:()=>void}){const overtime=draft?.kind==="overtime";return <Modal open={Boolean(draft)} onOpenChange={open=>!open&&!saving&&onClose()} eyebrow="Nómina · Incidencias" title={overtime?"Capturar horas extra":"Capturar inasistencias"} description={overtime?"El importe se calcula con la hora vigente, las horas extra y el multiplicador autorizado.":"Una inasistencia pagada queda registrada sin descuento; una no pagada descuenta días al valor diario vigente."} footer={<><Button disabled={saving} onClick={onClose}>Cancelar</Button><Button variant="primary" loading={saving} disabled={!draft?.rows.trim()} onClick={onSave}>Capturar incidencias</Button></>}>{draft&&<div className="batch-movement-form"><div className="payroll-guide"><CircleDollarSign size={18}/><span>{overtime?`Multiplicadores autorizados: ${multipliers.join(", ")}. Fórmula: valor hora × horas × multiplicador.`:"Fórmula de descuento: valor diario × días. Usa “pagada” o “no_pagada” en cada renglón."}</span></div><label className="operation-reason">{overtime?"Un renglón por colaborador: código [tab] fecha [tab] horas [tab] multiplicador [tab] descripción":"Un renglón por colaborador: código [tab] inicio [tab] fin [tab] días [tab] pagada/no_pagada [tab] descripción"}<textarea value={draft.rows} onChange={event=>onChange({...draft,rows:event.target.value})} rows={8} placeholder={overtime?"COL-000001\t2026-07-25\t3\t2\tTurno de cierre\nCOL-000002\t2026-07-25\t2.5\t1.5\tInventario":"COL-000001\t2026-07-25\t2026-07-25\t1\tno_pagada\tFalta\nCOL-000002\t2026-07-25\t2026-07-25\t1\tpagada\tPermiso autorizado"}/></label><label className="checkbox-field"><input type="checkbox" checked={draft.approve} onChange={event=>onChange({...draft,approve:event.target.checked})}/> Aprobar ahora para incluirlas en nómina</label><small>Hasta 100 renglones por lote. Se valida y guarda todo el lote o no se guarda nada.</small></div>}</Modal>}
function PendingIncidentsModal({open,items,total,page,selected,saving,onClose,onToggle,onToggleAll,onPageChange,onResolve}:{open:boolean;items:PendingIncident[];total:number;page:number;selected:string[];saving:boolean;onClose:()=>void;onToggle:(id:string)=>void;onToggleAll:()=>void;onPageChange:(page:number)=>void;onResolve:(action:"approve"|"reject")=>void}){const allSelected=items.length>0&&selected.length===items.length;return <Modal open={open} onOpenChange={value=>!value&&!saving&&onClose()} eyebrow="Nómina · Incidencias" title="Incidencias pendientes" description="Revisa el cálculo y aprueba o rechaza las incidencias seleccionadas. Sólo las aprobadas entran a nómina." footer={<><Button disabled={saving} onClick={onClose}>Cancelar</Button><Button variant="danger" loading={saving} disabled={!selected.length} onClick={()=>onResolve("reject")}>Rechazar seleccionadas</Button><Button variant="primary" loading={saving} disabled={!selected.length} onClick={()=>onResolve("approve")}>Aprobar seleccionadas</Button></>}>{items.length?<div className="pending-incidents"><label className="checkbox-field"><input aria-label="Seleccionar todas las incidencias" type="checkbox" checked={allSelected} onChange={onToggleAll}/> Seleccionar las {items.length} incidencias mostradas</label><Table><thead><tr><th></th><th>Colaborador</th><th>Incidencia</th><th>Cálculo</th><th>Importe</th></tr></thead><tbody>{items.map(item=>{const calculation=calculationLabel({concept_code:item.movement_type,calculation_metadata:item.calculation_metadata});return <tr key={item.id}><td><input aria-label={`Seleccionar incidencia de ${item.collaborator_name}`} type="checkbox" checked={selected.includes(item.id)} onChange={()=>onToggle(item.id)}/></td><td><strong>{item.collaborator_name}</strong><small>{item.collaborator_code}</small></td><td><strong>{item.movement_type==="overtime"?"Horas extra":"Inasistencia"}</strong><small>{date(item.effective_on)}{item.description?` · ${item.description}`:""}</small></td><td><small>{calculation||"Sin cálculo"}</small></td><td><strong className={item.movement_type==="absence"&&!item.paid?"is-reduction":""}>{item.movement_type==="absence"&&!item.paid?"−":""}{money(item.amount)}</strong></td></tr>;})}</tbody></Table><DataPagination page={page} onChange={onPageChange} total={total} pageSize={100} label="incidencias pendientes"/></div>:<div className="payroll-guide"><CheckCircle2 size={18}/><span>No hay incidencias pendientes por revisar.</span></div>}</Modal>}
function PayrollPaymentGroups({detail,saving,onLineMethod,onRecord}:{detail:PeriodDetail;saving:boolean;onLineMethod:(line:PeriodLine)=>void;onRecord:(method:PayablePaymentMethod)=>void}){const methods:PaymentMethod[]=["transfer","cash","other","unspecified"];const batches=new Map((detail.payment_batches??[]).map(batch=>[batch.payment_method,batch]));const groups=methods.map(method=>({method,lines:detail.lines.filter(line=>(line.payment_method??"unspecified")===method&&Number(line.total_pay)!==0)})).filter(group=>group.lines.length);return <section className="payroll-payment-groups"><div><strong>Pagos por método</strong><span>Registra cada grupo con su propia fecha y referencia. La corrida se cierra al registrar todos los grupos.</span></div>{groups.map(group=>{const total=group.lines.reduce((sum,line)=>sum+Number(line.total_pay),0);const batch=group.method==="unspecified"?null:batches.get(group.method);return <article key={group.method}><div><span>{paymentMethodLabel[group.method]}</span><strong>{money(total)}</strong><small>{group.lines.length} colaborador{group.lines.length===1?"":"es"}</small></div>{group.method==="unspecified"?<div className="payroll-payment-groups__undefined"><small>Asigna una forma de pago para poder registrar este grupo.</small>{group.lines.map(line=><Button key={line.id} size="sm" variant="secondary" disabled={saving} onClick={()=>onLineMethod(line)}>Asignar a {line.collaborator_name_snapshot}</Button>)}</div>:batch?<div className="payroll-payment-groups__recorded"><Badge tone="success">Registrado</Badge><small>{date(batch.payment_date)} · {batch.payment_reference}</small></div>:<Button size="sm" variant="primary" loading={saving} onClick={()=>onRecord(group.method as PayablePaymentMethod)}><WalletCards size={15}/>Registrar pago</Button>}</article>;})}</section>}
function PayrollLinePaymentMethodModal({draft,saving,onChange,onClose,onSave}:{draft:PayrollLinePaymentMethodDraft|null;saving:boolean;onChange:(draft:PayrollLinePaymentMethodDraft|null)=>void;onClose:()=>void;onSave:()=>void}){return <Modal open={Boolean(draft)} onOpenChange={open=>!open&&!saving&&onClose()} eyebrow="Pago" title="Forma de pago para esta corrida" description="Es una excepción de esta nómina; no modifica la forma predeterminada del colaborador." footer={<><Button disabled={saving} onClick={onClose}>Cancelar</Button><Button variant="primary" loading={saving} onClick={onSave}>Guardar excepción</Button></>}>{draft&&<div className="form-grid"><Field label="Colaborador"><Input value={draft.collaboratorName} disabled/></Field><Field label="Forma de pago"><Select ariaLabel="Forma de pago de la corrida" value={draft.paymentMethod} onValueChange={value=>onChange({...draft,paymentMethod:value as PayablePaymentMethod})} options={[{value:"transfer",label:"Transferencia"},{value:"cash",label:"Efectivo"},{value:"other",label:"Otro"}]}/></Field></div>}</Modal>}
function PayrollPaymentBatchModal({draft,saving,onChange,onClose,onSave}:{draft:PaymentBatchDraft|null;saving:boolean;onChange:(draft:PaymentBatchDraft|null)=>void;onClose:()=>void;onSave:()=>void}){return <Modal open={Boolean(draft)} onOpenChange={open=>!open&&!saving&&onClose()} eyebrow="Pago" title={draft?`Registrar pago · ${paymentMethodLabel[draft.paymentMethod]}`:"Registrar pago"} description="La referencia se conserva para este grupo de pago y no puede modificarse al cerrar la nómina." footer={<><Button disabled={saving} onClick={onClose}>Cancelar</Button><Button variant="primary" loading={saving} disabled={!draft?.paymentDate||!draft.reference.trim()} onClick={onSave}>Registrar pago</Button></>}>{draft&&<div className="form-grid"><Field label="Fecha de pago"><Input required type="date" value={draft.paymentDate} onChange={event=>onChange({...draft,paymentDate:event.target.value})}/></Field><Field label="Referencia / comprobante"><Input required value={draft.reference} onChange={event=>onChange({...draft,reference:event.target.value})} placeholder="Ej. Folio o comprobante"/></Field></div>}</Modal>}
function MovementModal({draft,saving,onChange,onClose,onSave}:{draft:MovementDraft|null;saving:boolean;onChange:(draft:MovementDraft|null)=>void;onClose:()=>void;onSave:()=>void}){return <Modal open={Boolean(draft)} onOpenChange={open=>!open&&!saving&&onClose()} eyebrow="Movimiento" title="Registrar otro concepto" description="Registra bonos, aguinaldo, prima vacacional u otros ajustes. Horas extra e inasistencias se calculan desde Nómina." footer={<><Button disabled={saving} onClick={onClose}>Cancelar</Button><Button variant="primary" loading={saving} disabled={!draft?.amount||!draft.effectiveOn} onClick={onSave}>Guardar movimiento</Button></>}>{draft&&<div className="form-grid"><Field label="Concepto"><Select ariaLabel="Concepto" value={draft.movementType} onValueChange={value=>onChange({...draft,movementType:value})} options={[{value:"bonus",label:"Bono"},{value:"aguinaldo",label:"Aguinaldo"},{value:"vacation_premium",label:"Prima vacacional"},{value:"adjustment",label:"Ajuste"}]}/></Field><Field label="Tratamiento"><Select ariaLabel="Tratamiento" value={draft.direction} onValueChange={value=>onChange({...draft,direction:value as MovementDraft["direction"]})} options={[{value:"addition",label:"Suma al pago"},{value:"reduction",label:"Resta al pago"},{value:"informational",label:"Sólo informativo"}]}/></Field><Field label="Fecha efectiva"><Input type="date" value={draft.effectiveOn} onChange={event=>onChange({...draft,effectiveOn:event.target.value})}/></Field><Field label="Unidades"><Input type="number" min="0" step="0.01" value={draft.units} onChange={event=>onChange({...draft,units:event.target.value})}/></Field><Field label="Importe"><Input type="number" min="0" step="0.01" value={draft.amount} onChange={event=>onChange({...draft,amount:event.target.value})}/></Field><Field label="Descripción"><Input value={draft.description} onChange={event=>onChange({...draft,description:event.target.value})}/></Field><label className="checkbox-field"><input type="checkbox" checked={draft.approve} onChange={event=>onChange({...draft,approve:event.target.checked})}/> Aprobar ahora para incluirlo en nómina</label></div>}</Modal>}
function MovementBatchModal({draft,saving,onChange,onClose,onSave}:{draft:MovementBatchDraft|null;saving:boolean;onChange:(draft:MovementBatchDraft|null)=>void;onClose:()=>void;onSave:()=>void}){return <Modal open={Boolean(draft)} onOpenChange={open=>!open&&!saving&&onClose()} eyebrow="Nómina" title="Otros conceptos por lote" description="Pega hasta 100 renglones preparados en Excel; Satrapy valida todo el lote antes de guardarlo." footer={<><Button disabled={saving} onClick={onClose}>Cancelar</Button><Button variant="primary" loading={saving} disabled={!draft?.rows.trim()||!draft.effectiveOn} onClick={onSave}>Validar y guardar lote</Button></>}>{draft&&<div className="batch-movement-form"><div className="form-grid"><Field label="Concepto"><Select ariaLabel="Concepto del lote" value={draft.movementType} onValueChange={value=>onChange({...draft,movementType:value})} options={[{value:"bonus",label:"Bono"},{value:"aguinaldo",label:"Aguinaldo"},{value:"vacation_premium",label:"Prima vacacional"},{value:"adjustment",label:"Ajuste"}]}/></Field><Field label="Tratamiento"><Select ariaLabel="Tratamiento del lote" value={draft.direction} onValueChange={value=>onChange({...draft,direction:value as MovementBatchDraft["direction"]})} options={[{value:"addition",label:"Suma al pago"},{value:"reduction",label:"Resta al pago"},{value:"informational",label:"Sólo informativo"}]}/></Field><Field label="Fecha efectiva"><Input type="date" value={draft.effectiveOn} onChange={event=>onChange({...draft,effectiveOn:event.target.value})}/></Field><label className="checkbox-field"><input type="checkbox" checked={draft.approve} onChange={event=>onChange({...draft,approve:event.target.checked})}/> Aprobar ahora para incluirlos en nómina</label></div><label className="operation-reason">Un renglón por colaborador: código [tab] importe [tab] unidades [tab] descripción<textarea value={draft.rows} onChange={event=>onChange({...draft,rows:event.target.value})} rows={8} placeholder={"COL-000001\t450\t3\tBono de productividad\nCOL-000002\t300\t2\tAjuste autorizado"}/></label><small>Usa el código automático del Directorio. El lote se guarda completo o no se guarda; no hay altas manuales repetitivas.</small></div>}</Modal>}
function TimeOffModal({draft,saving,onChange,onClose,onSave}:{draft:TimeOffDraft|null;saving:boolean;onChange:(draft:TimeOffDraft|null)=>void;onClose:()=>void;onSave:()=>void}){return <Modal open={Boolean(draft)} onOpenChange={open=>!open&&!saving&&onClose()} eyebrow="Vacaciones" title="Registrar vacaciones" description="Las vacaciones aprobadas actualizan el saldo del colaborador." footer={<><Button disabled={saving} onClick={onClose}>Cancelar</Button><Button variant="primary" loading={saving} disabled={!draft?.days||!draft.startsOn||!draft.endsOn} onClick={onSave}>Guardar vacaciones</Button></>}>{draft&&<div className="form-grid"><Field label="Inicio"><Input type="date" value={draft.startsOn} onChange={event=>onChange({...draft,startsOn:event.target.value})}/></Field><Field label="Fin"><Input type="date" value={draft.endsOn} onChange={event=>onChange({...draft,endsOn:event.target.value})}/></Field><Field label="Días"><Input type="number" min="0.5" step="0.5" value={draft.days} onChange={event=>onChange({...draft,days:event.target.value})}/></Field><Field label="Notas"><Input value={draft.notes} onChange={event=>onChange({...draft,notes:event.target.value})}/></Field><label className="checkbox-field"><input type="checkbox" checked={draft.approve} onChange={event=>onChange({...draft,approve:event.target.checked})}/> Aprobar ahora</label></div>}</Modal>}
function VacationBalanceModal({draft,saving,onChange,onClose,onSave}:{draft:VacationBalanceDraft|null;saving:boolean;onChange:(draft:VacationBalanceDraft|null)=>void;onClose:()=>void;onSave:()=>void}){return <Modal open={Boolean(draft)} onOpenChange={open=>!open&&!saving&&onClose()} eyebrow="Vacaciones" title="Ajustar saldo anual" description="Los días usados se calculan desde las vacaciones aprobadas; aquí sólo se configura lo otorgado y cualquier ajuste justificado." footer={<><Button disabled={saving} onClick={onClose}>Cancelar</Button><Button variant="primary" loading={saving} disabled={!draft?.year||!draft.grantedDays} onClick={onSave}>Guardar saldo</Button></>}>{draft&&<div className="form-grid"><Field label="Año"><Input type="number" min="2000" max="2200" value={draft.year} onChange={event=>onChange({...draft,year:event.target.value})}/></Field><Field label="Días otorgados"><Input type="number" min="0" step="0.5" value={draft.grantedDays} onChange={event=>onChange({...draft,grantedDays:event.target.value})}/></Field><Field label="Ajuste de días"><Input type="number" step="0.5" value={draft.adjustmentDays} onChange={event=>onChange({...draft,adjustmentDays:event.target.value})}/></Field><Field label="Motivo / nota"><Input value={draft.notes} onChange={event=>onChange({...draft,notes:event.target.value})}/></Field></div>}</Modal>}
function TerminationModal({draft,saving,onChange,onClose,onSave}:{draft:TerminationDraft|null;saving:boolean;onChange:(draft:TerminationDraft|null)=>void;onClose:()=>void;onSave:()=>void}){return <Modal open={Boolean(draft)} onOpenChange={open=>!open&&!saving&&onClose()} eyebrow="Colaborador" title="Dar de baja" description="El expediente y los pagos históricos se conservan. Desde esta fecha no se incluirá en periodos posteriores." footer={<><Button disabled={saving} onClick={onClose}>Cancelar</Button><Button variant="danger" loading={saving} disabled={!draft?.terminatedAt||!draft.reason.trim()} onClick={onSave}>Confirmar baja</Button></>}>{draft&&<div className="form-grid"><Field label="Colaborador"><Input value={draft.displayName} disabled/></Field><Field label="Fecha de baja"><Input required type="date" min={draft.hiredAt} value={draft.terminatedAt} onChange={event=>onChange({...draft,terminatedAt:event.target.value})}/></Field><Field label="Motivo"><Input required value={draft.reason} onChange={event=>onChange({...draft,reason:event.target.value})} placeholder="Ej. Terminación de relación laboral"/></Field></div>}</Modal>}
function movementLabel(type:string){return type==="overtime"?"Horas extra":type==="bonus"?"Bono":type==="aguinaldo"?"Aguinaldo":type==="vacation_premium"?"Prima vacacional":type==="absence"?"Ausencia":"Ajuste";}
